    {
        "tag": "godot-rooms",
        "user": "Procedural room generation for a Godot dungeon using TileMapLayer and a seed.",
        "assistant": "extends Node2D\n\n@export var tilemap: TileMapLayer\n@export var atlas: TileSetAtlasSource\n@export var room_min := 4\n@export var room_max := 9\n@export var map_size := 40\n@export var seed_value := 0\n\nvar rng := RandomNumberGenerator.new()\nconst FLOOR := Vector2i(0, 0)\nconst WALL := Vector2i(1, 0)\n\nfunc generate() -> void:\n\trng.seed = seed_value\n\ttilemap.clear()\n\n\t# fill with walls\n\tfor x in map_size:\n\t\tfor y in map_size:\n\t\t\ttilemap.set_cell(Vector2i(x, y), 0, WALL)\n\n\t# carve rooms + connect with corridors\n\tvar rooms: Array[Rect2i] = []\n\tfor i in 20:\n\t\tvar w := rng.randi_range(room_min, room_max)\n\t\tvar h := rng.randi_range(room_min, room_max)\n\t\tvar x := rng.randi_range(1, map_size - w - 2)\n\t\tvar y := rng.randi_range(1, map_size - h - 2)\n\t\tvar rect := Rect2i(x, y, w, h)\n\t\trooms.append(rect)\n\t\t_carve_rect(rect)\n\n\t# connect consecutive rooms\n\tfor i in rooms.size() - 1:\n\t\t_carve_corridor(rooms[i].get_center(), rooms[i + 1].get_center())\n\nfunc _carve_rect(rect: Rect2i) -> void:\n\tfor x in rect.size.x:\n\t\tfor y in rect.size.y:\n\t\t\ttilemap.set_cell(rect.position + Vector2i(x, y), 0, FLOOR)\n\nfunc _carve_corridor(a: Vector2i, b: Vector2i) -> void:\n\tvar x := a.x\n\tvar y := a.y\n\twhile x != b.x:\n\t\ttilemap.set_cell(Vector2i(x, y), 0, FLOOR)\n\t\tx += 1 if b.x > x else -1\n\twhile y != b.y:\n\t\ttilemap.set_cell(Vector2i(x, y), 0, FLOOR)\n\t\ty += 1 if b.y > y else -1",
    },
