def _load_schema():
    p = os.path.join(HERE, "schema", "kodr-map-v1.json")
    with open(p, "r", encoding="utf-8") as f:
        schema = json.load(f)
    return json.dumps(schema, indent=2)


def main():
    schema = _load_schema()
    examples = []
    for ex in EXAMPLES:
        user = ex["user"]
        if ex["tag"].startswith("map-"):
            user += "\n\nReference schema:\n" + schema
        examples.append(
            {
                "messages": [
                    {"role": "system", "content": SYSTEM},
                    {"role": "user", "content": user},
                    {"role": "assistant", "content": ex["assistant"]},
                ],
                "tags": [ex["tag"], *_engine_tags(ex["tag"])],
            }
        )

    with open(OUT, "w", encoding="utf-8") as f:
        for ex in examples:
            f.write(json.dumps(ex, ensure_ascii=False) + "\n")

    n = len(examples)
    per_engine = {}
    for ex in examples:
        for tag in ex["tags"]:
            per_engine[tag] = per_engine.get(tag, 0) + 1
    print(f"Wrote {n} curated examples -> {OUT}")
    print(f"Tags: {json.dumps(per_engine, indent=2)}")


def _engine_tags(tag):
    if tag.startswith("roblox"):
        return ["roblox", "luau"]
    if tag.startswith("unity"):
        return ["unity", "csharp"]
    if tag.startswith("godot"):
        return ["godot", "gdscript"]
    if tag.startswith("unreal"):
        return ["unreal", "cpp"]
    if tag.startswith("convert"):
        return ["maps", "conversion"]
    if tag.startswith("map"):
        return ["maps", "schema"]
    return ["design"]


if __name__ == "__main__":
    main()